import type { DataState } from './telemetry';

export type AlertSeverity = 'INFO' | 'WARNING' | 'HIGH' | 'CRITICAL';
export type AlertStatus = 'NEW' | 'ACKNOWLEDGED' | 'ASSIGNED' | 'RESOLVED' | 'DISMISSED';

export interface SourceStateRef {
  input: string;
  sourceLabel: string;
  state: DataState;
  observedAt: string;
}

/** Spec §9.1 / §11.3 RecommendationAlert. */
export interface RecommendationAlert {
  alertId: string;
  scenarioId: string;
  /** SCENARIO = generated by a scripted fixture; RULE = generated by a live-provider rule (§9.2). */
  origin: 'SCENARIO' | 'RULE';
  severity: AlertSeverity;
  title: string;
  observation: string;
  impact: string;
  contributingFactors: string[];
  /** Each item is a suggestion for an authorized human — never executed by this PoC. */
  recommendations: string[];
  assumptions: string[];
  entityIds: string[];
  sourceStates: SourceStateRef[];
  status: AlertStatus;
  owner?: string;
  notes: { at: string; by: string; text: string }[];
  createdAt: string;
  archived: boolean;
}

export type EventKind =
  | 'SCENARIO_RUN' | 'SCENARIO_ACTIVE' | 'SCENARIO_RESET' | 'SCENARIO_ERROR'
  | 'ALERT_CREATED' | 'ALERT_STATUS' | 'ALERT_NOTE' | 'ALERT_ASSIGNED'
  | 'ROLE_CHANGED' | 'DATA_MODE_CHANGED' | 'ASSUMPTIONS_CHANGED' | 'CONFIG_CHANGED' | 'ENVIRONMENT_RESET';

export interface EventLogEntry {
  id: number;
  at: string;
  kind: EventKind;
  actorRole: string;
  detail: string;
  alertId?: string;
}
